package ru.neverland.townyseasons.markets;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.inventory.*;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;

/** Every button uses the exact stored quote; pending database work never changes displayed stock. */
public final class SeasonMarketsMenu implements Listener {
    private enum Page{STOCK,ENTRIES,CITIES,TEMPLATES,QUOTE,DETAIL}
    private static final int[] CONTENT={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34};
    private final JavaPlugin plugin;private final SeasonMarketsService service;
    private static final class Holder implements InventoryHolder{
        final UUID viewer,town,receipt=UUID.randomUUID();final Inventory previous;final Page page;final int number;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;boolean busy;Map<String,Object> row;
        Holder(Player p,UUID town,Inventory previous,Page page,int number){viewer=p.getUniqueId();this.town=town;this.previous=previous;this.page=page;this.number=number;}
        public Inventory getInventory(){return inventory;}
    }
    public SeasonMarketsMenu(JavaPlugin plugin,SeasonMarketsService service){this.plugin=plugin;this.service=service;}
    private static ItemStack item(Material m,String title,List<String> lore){var i=new ItemStack(m);var meta=i.getItemMeta();meta.displayName(MenuStyle.nameComponent(MenuStyle.decode(title)));meta.lore(MenuStyle.loreComponents(lore.stream().map(MenuStyle::decode).toList()));i.setItemMeta(meta);return i;}
    private static String error(Throwable e){while((e instanceof CompletionException||e instanceof java.lang.reflect.InvocationTargetException)&&e.getCause()!=null)e=e.getCause();return e.getMessage()==null?"Операция не завершена; обновите список":e.getMessage();}
    private void button(Holder h,int slot,Material m,String title,List<String> lore,Runnable action){h.inventory.setItem(slot,item(m,title,lore));if(action!=null)h.actions.put(slot,action);}
    private Holder base(Player p,Inventory previous,Page page,int number,String title){var own=service.city(p);var h=new Holder(p,own.id(),previous,page,number);h.inventory=MenuStyle.inventory(plugin,h,54,title);button(h,45,Material.ARROW,"&e← Назад",List.of("Вернуться в предыдущее меню"),()->MenuStyle.returnTo(p,previous));button(h,53,Material.BARRIER,"&cЗакрыть",List.of("Закрыть меню"),p::closeInventory);p.openInventory(h.inventory);return h;}
    private boolean owns(Player p,Holder h){if(!plugin.isEnabled()||!p.isOnline()||p.getOpenInventory().getTopInventory().getHolder()!=h)return false;try{return h.town.equals(service.city(p).id());}catch(RuntimeException e){return false;}}
    private <T>void request(Player p,Holder h,Supplier<CompletionStage<T>> work,Consumer<T> done){if(h.busy)return;h.busy=true;button(h,4,Material.CLOCK,"&eСохраняем или загружаем…",List.of("Дождитесь подтверждения","Повторное нажатие не требуется"),null);try{work.get().whenComplete((value,failure)->{if(!plugin.isEnabled())return;SuiteScheduler.entityLater(plugin,p,()->{if(!owns(p,h))return;h.busy=false;if(failure!=null){button(h,4,Material.BARRIER,"&cНе удалось завершить",List.of(error(failure),"Сохранённые запасы остаются у города"),null);}else{h.inventory.setItem(4,null);try{done.accept(value);}catch(RuntimeException failed){button(h,4,Material.BARRIER,"&cНе удалось открыть",List.of(error(failed)),null);}}},()->{},1);});}catch(RuntimeException e){h.busy=false;button(h,4,Material.BARRIER,"&cДействие недоступно",List.of(error(e)),null);}}
    public void openStock(Player p,Inventory previous,int page){try(var guard=SuiteState.guard()){
        var h=base(p,previous,Page.STOCK,page,"Сезонный запас города");button(h,49,Material.CLOCK,"&aОбновить",List.of("Только подтверждённые партии"),()->openStock(p,previous,page));button(h,47,Material.CHEST,"&eПодготовить запас",List.of("Отложить готовую продукцию к следующему сезону","Количество и срок будут показаны до подтверждения","Резерв можно отменить с полным возвратом","Подтверждает мэр города"),()->quote(p,h.inventory,()->service.preparation(p)));button(h,51,Material.EMERALD,"&bЯрмарка и история",List.of("Предложения соседних городов","История резервов и обменов"),()->openEntries(p,h.inventory,1));request(p,h,()->service.stock(p,page),rows->{int n=0;for(var row:rows)button(h,CONTENT[n++],Material.BARREL,"&e"+row.get("title"),List.of("&fСвободно: &a"+row.get("available"),"&fВ резервах: &e"+row.get("reserved"),"&fПроизведено городом: "+row.get("produced"),"&fПолучено обменом: "+row.get("received"),"&fПередано обменом: "+row.get("sent"),"","&7Партии выпускаются из реально сданных материалов."),null);if(rows.isEmpty())button(h,22,Material.PAPER,"&eГотовых партий пока нет",List.of("Откройте производство специализации города","и завершите выпуск из реальных материалов."),null);pages(p,h,rows.size()==20,()->openStock(p,previous,page-1),()->openStock(p,previous,page+1));});
    }}
    public void openEntries(Player p,Inventory previous,int page){try(var guard=SuiteState.guard()){
        var h=base(p,previous,Page.ENTRIES,page,"Ярмарка • предложения и история");button(h,49,Material.CLOCK,"&aОбновить",List.of("Проверить сохранённые результаты"),()->openEntries(p,previous,page));var date=service.calendar(h.town);String reason=service.problem();if(reason.isBlank()){var c=service.catalog();reason=date.closedReason(c.fairDays(),c.undated());}button(h,47,Material.EMERALD,"&eПредложить обмен",List.of("Выбрать город и точные условия",reason,"Первый мэр резервирует свой товар","Второй мэр подтверждает обмен целиком"),()->cities(p,h.inventory,1));request(p,h,()->service.entries(p,page),rows->{int n=0;for(var row:rows){var id=UUID.fromString((String)row.get("id"));button(h,CONTENT[n++],Material.WRITABLE_BOOK,"&e"+row.get("title"),summary(row,h.town),()->detail(p,h.inventory,id));}if(rows.isEmpty())button(h,22,Material.PAPER,"&eПредложений пока нет",List.of("Здесь появятся ваши резервы,","входящие предложения и завершённые обмены."),null);pages(p,h,rows.size()==20,()->openEntries(p,previous,page-1),()->openEntries(p,previous,page+1));});
    }}
    private void cities(Player p,Inventory previous,int page){var h=base(p,previous,Page.CITIES,page,"Ярмарка • выбрать город");var rows=service.cities(p,page);int n=0;for(var city:rows)button(h,CONTENT[n++],Material.OAK_SIGN,"&e"+city.name(),List.of("Предложить обмен готовой продукцией","Город в том же мире сезонного календаря"),()->templates(p,h.inventory,city));if(rows.isEmpty())button(h,22,Material.PAPER,"&eДругих городов нет",List.of("Обмен доступен между городами одного мира."),null);pages(p,h,rows.size()==21,()->cities(p,previous,page-1),()->cities(p,previous,page+1));}
    private void templates(Player p,Inventory previous,SeasonMarketsService.City city){var h=base(p,previous,Page.TEMPLATES,1,"Условия обмена • "+city.name());int n=0;for(var offer:service.catalog().exchanges().values())button(h,CONTENT[n++],Material.PAPER,"&e"+offer.title(),List.of("Получатель: "+city.name(),"Нажмите, чтобы увидеть точный состав и срок","До отдельного подтверждения ничего не резервируется"),()->quote(p,h.inventory,()->service.exchange(p,city.id(),offer.id())));}
    private void quote(Player p,Inventory previous,Supplier<CompletionStage<Map<String,Object>>> source){var h=base(p,previous,Page.QUOTE,1,"Проверить условия");request(p,h,source,row->{h.row=row;button(h,22,Material.WRITABLE_BOOK,"&e"+row.get("title"),summary(row,h.town),null);button(h,40,Material.LIME_DYE,"&aПодтвердить резерв",List.of("Указанные партии будут отложены на указанный срок","OFFER".equals(row.get("kind"))?"Обмен завершится после согласия второго мэра":"Запас хранится до указанного срока","Отмена возвращает резерв полностью"),()->request(p,h,()->service.confirm(p,h.row),saved->detail(p,previous,UUID.fromString((String)saved.get("id")))));});}
    private void detail(Player p,Inventory previous,UUID id){var h=base(p,previous,Page.DETAIL,1,"Сезонная квитанция");button(h,49,Material.CLOCK,"&aОбновить",List.of("Прочитать сохранённый результат"),()->detail(p,previous,id));request(p,h,()->service.entry(id),row->{h.row=row;if(!h.town.toString().equals(row.get("town"))&&!h.town.toString().equals(row.get("other")))throw new IllegalArgumentException("Квитанция другого города");button(h,22,Material.WRITABLE_BOOK,"&e"+row.get("title"),summary(row,h.town),null);if("HELD".equals(row.get("state"))){if(!service.mayor(p))button(h,40,Material.GRAY_DYE,"&7Решение принимает мэр",List.of("Вы можете просмотреть точные условия"),null);else if(h.town.toString().equals(row.get("town")))button(h,40,Material.ORANGE_DYE,"&eОтменить и вернуть резерв",List.of("Все отложенные партии вернутся городу","Штрафа и потери материалов нет"),()->request(p,h,()->service.cancel(p,id),saved->detail(p,previous,id)));else button(h,40,Material.LIME_DYE,"&aПодтвердить точный обмен",List.of("Город передаст указанные партии","и одновременно получит встречный товар","Если товара или места не хватает, обмен не состоится"),()->request(p,h,()->service.accept(p,h.row,h.receipt),saved->detail(p,previous,id)));}});}
    private void pages(Player p,Holder h,boolean next,Runnable before,Runnable after){if(h.number>1)button(h,48,Material.ARROW,"&eПредыдущая страница",List.of("Страница "+(h.number-1)),before);if(next)button(h,50,Material.ARROW,"&eСледующая страница",List.of("Страница "+(h.number+1)),after);}
    @SuppressWarnings("unchecked")private static List<String> summary(Map<String,Object> row,UUID viewer){var lore=new ArrayList<String>();lore.add("&fГород: &e"+row.get("townName"));if(!"".equals(row.get("other")))lore.add("&fПолучатель: &e"+row.get("otherName"));String state=(String)row.getOrDefault("state","QUOTE");lore.add("&fСостояние: "+switch(state){case"HELD"->"&eВ резерве, ожидает решения";case"SWAPPED"->"&aОбмен завершён";case"CANCELLED"->"&7Отменено, резерв возвращён";case"EXPIRED"->"&7Срок закончился, резерв возвращён";default->"&eПроверьте перед подтверждением";});var labels=(Map<String,String>)row.get("labels");var give=(Map<String,Number>)row.get("give");var receive=(Map<String,Number>)row.get("receive");boolean own=viewer.toString().equals(row.get("town"));lore.add("");lore.add(own?"&fНаш город отдаёт / откладывает:":"&fНаш город получает:");give.forEach((id,count)->lore.add("&e"+labels.get(id)+" × "+count));if(!receive.isEmpty()){lore.add(own?"&fНаш город получает:":"&fНаш город отдаёт:");receive.forEach((id,count)->lore.add("&e"+labels.get(id)+" × "+count));}long expires=((Number)row.get("expires")).longValue();lore.add("");lore.add("&fДо: "+java.time.format.DateTimeFormatter.ofPattern("dd.MM HH:mm").withZone(java.time.ZoneId.of("Europe/Moscow")).format(java.time.Instant.ofEpochMilli(expires))+" МСК");lore.add("&7Условия этой квитанции не меняются.");if(row.get("reason") instanceof String reason&&!reason.isBlank())lore.add("&7"+reason);return lore;}
    @EventHandler public void click(InventoryClickEvent e){try(var guard=SuiteState.guard()){if(!(e.getView().getTopInventory().getHolder() instanceof Holder h))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(h.viewer)||!owns(p,h)||h.busy)return;try{if(SuiteState.frozen(plugin.getName()))throw new IllegalArgumentException("Сезонные операции приостановлены; запасы сохранены");var action=h.actions.get(e.getRawSlot());if(action!=null)action.run();}catch(RuntimeException failure){p.sendMessage(MenuStyle.decode("&c"+error(failure)));}}}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof Holder)e.setCancelled(true);}
}
